code_examples:
// Button: legacy -> new API
// Legacy usage
<Button kind="primary" size="sm">Save</Button>

// Recommended usage (semantic tokens + explicit tone)
<Button tone="positive" density="compact">Save</Button>

// Token rename example (CSS variables)
/* Legacy */
--rwd-color-primary: #0b5fff;
/* Semantic */
--rwd-color-brand-accent: var(--rwd-color-primary); /* mapping for migration */

// Table: migrating from columnDefs to column schema v2
// Legacy
<Table columns={[{key: 'name', label: 'Name'}]} data={rows} />
// New API (typed, sortable by default)
<Table schema={[{id: 'name', header: 'Name', sortable: true, accessor: r => r.name}]} data={rows} />

// Chart: legacy config -> new prop-forwarding
// Legacy config object
<LineChart config={{xKey: 'date', yKey: 'value', stroke: '#3A7'}} />
// New usage (props + typed series)
<LineChart series={[{id: 'value', color: 'brandGreen', accessor: 'value'}]} xAccessor='date' />
